/**
 * Hand-written service worker.
 * - App shell (HTML, JS, CSS, data, fonts, sfx) is precached under a content-hashed name
 *   generated by `npm run sw` (precache-manifest.js). A new hash = a new version.
 * - Pokémon artwork and icons are cached on first use (cache-first) in a cache that survives
 *   app updates. Cries are left to the HTTP cache (streamed with Range requests).
 * - A new version waits until the page confirms the update (message SKIP_WAITING).
 *
 * The file name is the one the previous (Vue CLI / workbox) version registered, so returning
 * players get this worker through the normal update check: the old app shows its "update
 * available" hint and its SKIP_WAITING message activates this worker, which then serves
 * the new app and removes the old caches.
 */
importScripts('./precache-manifest.js')

const { version, files } = self.__PRECACHE
const SHELL_CACHE = `pg-shell-${version}`
const MEDIA_CACHE = 'pg-media-v1'
const scope = new URL(self.registration.scope)
const MEDIA_PATH = new URL('assets/pokemon/', scope).pathname

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      .then((cache) => cache.addAll(files.map((f) => new Request(new URL(f, scope), { cache: 'reload' }))))
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      // Removes old shell versions and caches of the previous (workbox based) app version.
      for (const key of await caches.keys()) {
        if (key !== SHELL_CACHE && key !== MEDIA_CACHE) await caches.delete(key)
      }
      await self.clients.claim()
    })()
  )
})

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting()
})

self.addEventListener('fetch', (event) => {
  const { request } = event
  if (request.method !== 'GET') return
  const url = new URL(request.url)
  if (url.origin !== scope.origin) return

  if (request.mode === 'navigate') {
    event.respondWith(
      caches
        .match(new URL('index.html', scope), { cacheName: SHELL_CACHE })
        .then((cached) => cached ?? fetch(request))
    )
    return
  }

  if (url.pathname.startsWith(MEDIA_PATH)) {
    // Cries are streamed by <audio> with Range requests; leave them to the HTTP cache.
    if (url.pathname.startsWith(`${MEDIA_PATH}sounds/`)) return
    event.respondWith(cacheFirst(request, MEDIA_CACHE))
    return
  }

  event.respondWith(
    caches
      .match(request, { cacheName: SHELL_CACHE, ignoreSearch: true })
      .then((cached) => cached ?? fetch(request))
  )
})

async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName)
  const cached = await cache.match(request)
  if (cached) return cached
  const response = await fetch(request)
  if (response.status === 200) cache.put(request, response.clone()).catch(() => {})
  return response
}
